    // 辅助函数：兼容 string 与多模态 Array 结构的 message.content
    function getMsgText(m) {
        if (!m) return '';
        if (typeof m.content === 'string') return m.content;
        if (Array.isArray(m.content)) {
            return m.content.map(p => (p && typeof p.text === 'string' ? p.text : '')).join('\n');
        }
        return '';
    }

    function setMsgText(m, newText) {
        if (!m) return;
        if (typeof m.content === 'string') {
            m.content = newText;
        } else if (Array.isArray(m.content)) {
            let replaced = false;
            m.content = m.content.map(p => {
                if (!replaced && p && typeof p.text === 'string') {
                    replaced = true;
                    return Object.assign({}, p, { text: newText });
                }
                return p;
            });
            if (!replaced) {
                m.content.push({ type: 'text', text: newText });
            }
        }
    }

    function injectHeaderAndSessionPrefix(m, thinkingPlan) {
        if (!m || !thinkingPlan) return;
        const effortHdr = thinkingPlan.headerMode ? resolveArgonEffortHeader(thinkingPlan.headerMode) : '';
        const sessionLine = thinkingPlan.sessionSalt ? `[Session-ID: ${genRandomHex('SID', 2)}]` : '';
        if (!effortHdr && !sessionLine) return;

        const applyToText = raw => {
            let text = String(raw ?? '');
            const effortRx = /^SPECIAL INSTRUCTION:\s*think silently if needed\.\s*EFFORT LEVEL:\s*[0-9.]+\.\s*/m;
            const hasEffort = effortRx.test(text);
            const hasSession = /\[Session-ID:/i.test(text);
            const needEffort = Boolean(effortHdr && !hasEffort);
            const needSession = Boolean(sessionLine && !hasSession);
            if (!needEffort && !needSession) return text;
            if (!needEffort && needSession && hasEffort) {
                // auto 透传模式保留了预设自带的 EFFORT LEVEL 头时，把 Session-ID 插在其下一行，不吞掉 Session-ID
                return text.replace(
                    /^(SPECIAL INSTRUCTION:\s*think silently if needed\.\s*EFFORT LEVEL:\s*[0-9.]+\.[ \t]*\r?\n?)/m,
                    `$1${sessionLine}\n`
                );
            }
            const parts = [];
            if (needEffort) parts.push(effortHdr);
            if (needSession) parts.push(sessionLine);
            return parts.join('\n') + '\n' + text;
        };

        if (typeof m.content === 'string') {
            m.content = applyToText(m.content);
        } else if (Array.isArray(m.content)) {
            for (let i = 0; i < m.content.length; i++) {
                const p = m.content[i];
                if (p && typeof p.text === 'string') {
                    m.content[i] = Object.assign({}, p, { text: applyToText(p.text) });
                    return;
                }
            }
        }
    }

    function prependToMsgContent(m, prefix) {
        if (!m) return;
        if (typeof m.content === 'string') {
            if (!m.content.includes('SPECIAL INSTRUCTION:')) {
                m.content = prefix + m.content;
            }
        } else if (Array.isArray(m.content)) {
            for (let i = 0; i < m.content.length; i++) {
                const p = m.content[i];
                if (p && typeof p.text === 'string') {
                    if (!p.text.includes('SPECIAL INSTRUCTION:')) {
                        m.content[i] = Object.assign({}, p, { text: prefix + p.text });
                    }
                    return;
                }
            }
        }
    }

    function appendToMsgContent(m, suffix, checkMarker) {
        if (!m) return false;
        if (typeof m.content === 'string') {
            if (!m.content.trim()) return false;
            if (!m.content.includes(checkMarker)) {
                m.content = m.content.trimEnd() + '\n\n' + suffix;
            }
            return true;
        } else if (Array.isArray(m.content)) {
            if (m.content.some(p => p && typeof p.text === 'string' && p.text.includes(checkMarker))) {
                return true;
            }
            for (let i = m.content.length - 1; i >= 0; i--) {
                const p = m.content[i];
                if (p && typeof p.text === 'string' && p.text.trim()) {
                    m.content[i] = Object.assign({}, p, { text: p.text.trimEnd() + '\n\n' + suffix });
                    return true;
                }
            }
            if (m.content.length > 0) {
                m.content = [...m.content, { type: 'text', text: suffix }];
                return true;
            }
        }
        return false;
    }

