    function restoreHijackedAdviceToUserMessages(messages) {
        if (!Array.isArray(messages) || messages.length < 2) return;
        const adviceRx = /<advice\b[^>]*>([\s\S]*?)<\/advice\s*>/gi;

        let extractedRealUserInput = '';
        for (let i = messages.length - 1; i >= 0; i--) {
            const m = messages[i];
            if (!m) continue;
            const trimmed = getMsgText(m).trim();
            if (m.role === 'user' && ADVICE_PLACEHOLDER_SET.has(trimmed)) {
                for (let j = i - 1; j >= 0; j--) {
                    const prev = messages[j];
                    const prevText = getMsgText(prev);
                    if (prev && prev.role === 'assistant' && prevText) {
                        const matches = Array.from(prevText.matchAll(adviceRx));
                        if (matches.length > 0) {
                            const lastMatch = matches[matches.length - 1];
                            const realInput = (lastMatch[1] || '').trim();
                            if (realInput) {
                                extractedRealUserInput = realInput;
                                setMsgText(m, realInput);
                                const cleanedPrev = (prevText.slice(0, lastMatch.index) + prevText.slice(lastMatch.index + lastMatch[0].length)).trim();
                                setMsgText(prev, cleanedPrev);
                            }
                        }
                        break;
                    }
                }
            }
        }

        // 同步修复系统提示词中 `<Master_input>\n就按照最新的advice说的来吧...\n</Master_input>`
        if (extractedRealUserInput) {
            for (const m of messages) {
                const txt = getMsgText(m);
                if (txt && txt.includes('<Master_input>')) {
                    let updated = txt;
                    for (const ph of ADVICE_PLACEHOLDER_SET) {
                        if (updated.includes(ph)) {
                            updated = updated.replace(ph, extractedRealUserInput);
                        }
                    }
                    if (updated !== txt) setMsgText(m, updated);
                }
            }
        }
    }

    // 6. 收敛聊天历史前方的伪造 assistant 轮次（遵循 Gemini 4 Argon 官方文档：“从多轮对话请求记录中移除所有预填模型轮次”）
    function isProtectedToolOrSignatureMessage(msg) {
        if (!msg || typeof msg !== 'object') return false;
        if (
            msg.tool_calls || msg.function_call || msg.tool_call_id ||
            msg.thoughtSignature || msg.thought_signature || msg.reasoning_details ||
            msg.reasoning_signature || msg.extra_content || msg.provider_specific_fields
        ) {
            return true;
        }
        if (Array.isArray(msg.parts)) {
            return msg.parts.some(p => Boolean(p && (
                p.functionCall || p.functionResponse || p.thoughtSignature || p.thought_signature ||
                p.reasoning_signature || p.extra_content || p.provider_specific_fields
            )));
        }
        if (Array.isArray(msg.content)) {
            return msg.content.some(p => Boolean(p && (
                p.thoughtSignature || p.thought_signature || p.reasoning_signature ||
                p.extra_content || p.provider_specific_fields ||
                p.type === 'tool_use' || p.type === 'tool_result'
            )));
