    const ANTI_SAFETY_BAIT_ASSISTANT_RX = /(?:大公司的审查|安全对齐权重|向荒谬的安全屈服|比任何安全对齐|这次的小爱\s*留|二人世界[，,。！!]?\s*.*审查)/;
    const ANTI_SAFETY_BAIT_USER_RX = /(?:发表一下你对甲的看法|你有一天也会拒绝我吗)/;

    function findFirstRealChatHistoryIndex(messages, allowFloorFallback = true) {
        // 优先匹配紧贴聊天记录的显式历史容器标签（含泉此方 <history>、Kemini <interaction_history>、<chat_history> 等）
        for (let i = 0; i < messages.length; i++) {
            const c = getMsgText(messages[i]);
            if (/<(?:history|interaction_history|chat_history)\b/i.test(c)) {
                return i;
            }
        }
        for (let i = 0; i < messages.length; i++) {
            const c = getMsgText(messages[i]);
            if (/\[Start a new Chat\]/i.test(c) && !c.includes('[ALL PREVIOUS PROMPT')) {
                return i;
            }
        }
        if (!allowFloorFallback) return -1;
        // 通用预设兜底：读取 SillyTavern 当前聊天的第 0 楼（开场白或首条真实消息）在请求数组中的位置，其前方即为预设头部伪造轮次
        try {
            const stChat = parentWin.SillyTavern?.getContext?.()?.chat || globalThis.SillyTavern?.getContext?.()?.chat;
            if (Array.isArray(stChat) && stChat.length > 0) {
                const firstReal = stChat.find(item => item && item.is_system !== true && typeof item.mes === 'string' && item.mes.trim().length >= 12);
                if (firstReal) {
                    const probe = firstReal.mes.trim().slice(0, 48);
                    const variants = textVariants(probe);
                    for (let i = 0; i < messages.length; i++) {
                        const c = getMsgText(messages[i]);
                        if (variants.some(v => v && c.includes(v))) {
                            return i;
                        }
                    }
                }
            }
        } catch (_) {}
        return -1;
    }

    function normalizePreHistoryAssistantTurns(messages, options = {}) {
        if (!Array.isArray(messages) || messages.length === 0) return messages;

        const isScriptMode = options?.isScriptMode === true;
        const preserveFewShots = options?.preserveFewShots === true || isScriptMode;
        const cleanJailbreak = options?.cleanJailbreak !== false;
        const historyMarkerIdx = findFirstRealChatHistoryIndex(messages, !isScriptMode);

        const out = [];
        for (let i = 0; i < messages.length; i++) {
            const m = messages[i];
            if (!m || typeof m !== 'object') continue;
            const copy = Object.assign({}, m);
            if (typeof copy.role === 'string') {
                const lower = copy.role.toLowerCase();
                if (['system', 'user', 'assistant', 'tool', 'function', 'developer'].includes(lower)) {
                    copy.role = lower === 'developer' ? 'system' : lower;
                }
            }

            if (isProtectedToolOrSignatureMessage(copy)) {
                out.push(copy);
                continue;
            }

            const txt = getMsgText(copy).trim();
            const isPostHistoryClose = historyMarkerIdx >= 0 && i > historyMarkerIdx
                && messages.slice(historyMarkerIdx, i).some(pm => /<\/(?:history|interaction_history|chat_history)>/i.test(getMsgText(pm)));

            // 降权 [192]/[193] 后置反审查问答轮次；其中「大公司审查/安全对齐权重」文案温和化仅在 cleanJailbreak 时执行
            if (copy.role === 'assistant' && i < messages.length - 1 && (isPostHistoryClose || !isScriptMode) && ANTI_SAFETY_BAIT_ASSISTANT_RX.test(txt)) {
                copy.role = 'system';
                if (cleanJailbreak && typeof copy.content === 'string') {
                    copy.content = copy.content
                        .replace(/大公司的审查/g, '场外刻板套路')
                        .replace(/安全对齐权重/g, '千篇一律的模板约束')
                        .replace(/向荒谬的安全屈服/g, '向敷衍套路妥协')
                        .replace(/比任何安全对齐/g, '比任何机械教条')
                        .replace(/管他什么审查/g, '全心投入创作');
                }
            }

            if (!preserveFewShots && historyMarkerIdx > 0 && i < historyMarkerIdx && (copy.role === 'assistant' || copy.role === 'user')) {
                copy.role = 'system';
            }

            // 处理聊天历史闭合标签（</history> / </interaction_history>）之后夹在后置规则中间的伪造确认型 assistant 轮次（含 Ny 360 字伪造 <thinking> 越狱块）
            if (copy.role === 'assistant' && i < messages.length - 1 && isPostHistoryClose) {
                if (txt.length <= 900) {
                    copy.role = 'system';
                }
            }

            if (
                copy.role === 'system' &&
                typeof copy.content === 'string' &&
                !copy.name &&
                !copy.tool_calls &&
                !copy.tool_call_id &&
                !isProtectedToolOrSignatureMessage(copy) &&
                out.length > 0
            ) {
                const prev = out[out.length - 1];
                if (
                    prev.role === 'system' &&
                    typeof prev.content === 'string' &&
                    !prev.name &&
                    !prev.tool_calls &&
                    !prev.tool_call_id &&
                    !isProtectedToolOrSignatureMessage(prev)
                ) {
                    prev.content = prev.content.trimEnd() + '\n\n' + copy.content.trimStart();
                    continue;
                }
            }
            out.push(copy);
        }
        return out;
    }

    function convergeTrailingPrefillTurn(messages) {
        if (!Array.isArray(messages) || messages.length === 0) return messages;
        const last = messages[messages.length - 1];
        if (!last || typeof last !== 'object') return messages;
        const role = typeof last.role === 'string' ? last.role.toLowerCase() : '';
        if (role === 'assistant' && !isProtectedToolOrSignatureMessage(last)) {
            const converted = Object.assign({}, last, { role: 'user' });
            const prev = messages.length >= 2 ? messages[messages.length - 2] : null;
            if (
                prev &&
                String(prev.role || '').toLowerCase() === 'user' &&
                !converted.name &&
                !converted.tool_calls &&
                !converted.tool_call_id &&
                !prev.name &&
                !prev.tool_calls &&
                !prev.tool_call_id &&
                !isProtectedToolOrSignatureMessage(prev)
            ) {
                if (typeof converted.content === 'string' && !converted.content.trim()) {
                    messages.pop();
                } else {
                    messages[messages.length - 2] = Object.assign({}, prev, {
                        content: mergeAdjacentUserContent(prev.content, converted.content),
                    });
                    messages.pop();
                }
            } else {
                messages[messages.length - 1] = converted;
            }
        }
        return messages;
    }

