    const JSON_WIRE_ESCAPE_OPEN = '\uE01E';
    const JSON_WIRE_ESCAPE_CLOSE = '\uE01F';

    function toJsonUnicodeEscapeUnits(str) {
        let out = '';
        for (let i = 0; i < str.length; i += 1) {
            const code = str.charCodeAt(i);
            if (code > 0x7F) {
                out += '\\u' + code.toString(16).padStart(4, '0');
            } else if (code === 0x22) {
                out += '\\"';
            } else if (code === 0x5C) {
                out += '\\\\';
            } else if (code === 0x0A) {
                out += '\\n';
            } else if (code === 0x0D) {
                out += '\\r';
            } else if (code === 0x09) {
                out += '\\t';
            } else if (code < 0x20) {
                out += '\\u' + code.toString(16).padStart(4, '0');
            } else {
                out += str[i];
            }
        }
        return out;
    }

    function markTextForJsonWireEscape(value) {
        const s = String(value ?? '');
        if (!s || !/[^\x00-\x7F]/.test(s)) return s;
        if (s.includes(JSON_WIRE_ESCAPE_OPEN)) return s;
        return JSON_WIRE_ESCAPE_OPEN + s + JSON_WIRE_ESCAPE_CLOSE;
    }

    // 在 JSON.stringify 输出层将受标记区间的非 ASCII 字符转为标准单斜杠 \uXXXX 字面量：
    // 网关明文 WAF 无法匹配中文关键词，而酒馆后端/上游反代在 JSON.parse 时 100% 自动无损还原回原中文，0 额外 Token、0 理解负担！
    function stringifyWithWireUnicodeEscape(bodyObj, escapeAllNonAsciiInMessages = false) {
        const rawJson = JSON.stringify(bodyObj);
        if (!rawJson) return rawJson;
        let out = rawJson;
        if (out.includes(JSON_WIRE_ESCAPE_OPEN) || out.includes('\\ue01e') || out.includes('\\uE01E')) {
            const markerRx = /(?:\uE01E|\\u[eE]01[eE])([\s\S]*?)(?:\uE01F|\\u[eE]01[fF])/g;
            out = out.replace(markerRx, (_, inner) => {
                return inner.replace(/[^\x00-\x7F]/g, ch => '\\u' + ch.charCodeAt(0).toString(16).padStart(4, '0'));
            });
        }
        if (escapeAllNonAsciiInMessages) {
            // 仅对 JSON 字符串内部的非 ASCII UTF-16 码元转写为标准 \uXXXX，不触碰 ASCII 结构符，确保 100% 合法 JSON
            out = out.replace(/[^\x00-\x7F]/g, ch => '\\u' + ch.charCodeAt(0).toString(16).padStart(4, '0'));
        }
        return out;
    }

    const thGenStarts = [];
    let thTrackerInstalled = false;
    let thTrackerPrimeTries = 0;
    function installThGenerationTracker() {
        if (thTrackerInstalled) return true;
        for (const host of hostWindows()) {
            try {
                const ctx = host.SillyTavern && host.SillyTavern.getContext && host.SillyTavern.getContext();
                const es = ctx && ctx.eventSource;
                if (!es || typeof es.on !== 'function') continue;
                const clearThStarts = () => { thGenStarts.length = 0; };
                es.on('js_generation_started', () => { thGenStarts.push(Date.now()); });
                // 收到结束、停止或酒馆原生生成启动/结束时一律清空，杜绝后台脚本报错漏发 js_generation_ended 导致 5 分钟内正文被误判放行！
                es.on('js_generation_ended', clearThStarts);
                es.on('generation_stopped', clearThStarts);
                es.on('generation_ended', clearThStarts);
                const et = ctx.eventTypes || ctx.event_types;
                if (et) {
                    if (et.GENERATION_STOPPED) es.on(et.GENERATION_STOPPED, clearThStarts);
                    if (et.GENERATION_ENDED) es.on(et.GENERATION_ENDED, clearThStarts);
                    if (et.USER_MESSAGE_RENDERED) es.on(et.USER_MESSAGE_RENDERED, clearThStarts);
                }
                thTrackerInstalled = true;
                return true;
            } catch (_) {}
        }
        return false;
    }
    function primeThGenerationTracker() {
        if (installThGenerationTracker()) return;
        if (thTrackerPrimeTries++ >= 40) return;
        try { setTimeout(primeThGenerationTracker, 500); } catch (_) {}
    }
    function thGenerationActive() {
        installThGenerationTracker();
        // 酒馆助手调用在 emit('js_generation_started') 后紧接着发起请求，窗口保持 8 秒（与 v4.3.2 对齐），防止后台脚本漏发结束事件导致 25 秒内主正文被误判为插件请求而丢失工具流
        const limit = Date.now() - 8000;
        while (thGenStarts.length && thGenStarts[0] < limit) thGenStarts.shift();
        return thGenStarts.length > 0;
    }

    function isHistoricalAssistantContent(txt, floor) {
        const trimmed = String(txt || '').trim();
        if (!trimmed) return false;
        // 历史已完成回复通常会闭合 </konatan_planning~>，而预设尾部预填充只开标签不闭合
        if (trimmed.includes('</konatan_planning~>')) return true;
        const tailAssistants = Array.isArray(floor?.tailAssistants) ? floor.tailAssistants : [];
        return tailAssistants.some(tail => {
            if (!tail) return false;
            if (trimmed === tail) return true;
            const minOverlap = Math.max(80, Math.floor(tail.length * 0.5));
            return trimmed.length >= minOverlap && (tail.includes(trimmed) || trimmed.includes(tail));
        });
    }

    // 仅采集当前生效预设的系统提示与当前用户轮次之后的尾部指令/开放式预填充，排除历史对话轮次中的旧标签残留
    function collectPresetControlMessages(body, floor = null) {
        const messages = body && Array.isArray(body.messages) ? body.messages : [];
        if (!messages.length) return [];
        const resolvedFloor = floor && typeof floor === 'object' ? floor : readCurrentUserFloor();
        const userTurnIdx = currentUserTurnIndex(messages, resolvedFloor);
        const isContinue = String(body?.type || '').toLowerCase() === 'continue';
        const roleOf = m => String(m?.role || '').toLowerCase();
        const isOpenPrefill = m => !isContinue && !isHistoricalAssistantContent(getMsgText(m), resolvedFloor);
        let lastUserIdx = -1;
        if (userTurnIdx < 0) {
            for (let i = messages.length - 1; i >= 0; i -= 1) {
                if (roleOf(messages[i]) === 'user') {
                    lastUserIdx = i;
                    break;
                }
            }
        }
        return messages.filter((m, i) => {
            if (!m) return false;
            const role = roleOf(m);
            if (role === 'system' || role === 'developer') return true;
            if (userTurnIdx >= 0) {
                return i > userTurnIdx && (role === 'user' || (role === 'assistant' && isOpenPrefill(m)));
            }
            const isTrailingUserSuffix = role === 'user' && i === lastUserIdx && lastUserIdx > 0 && roleOf(messages[lastUserIdx - 1]) === 'user';
            const isAfterLastUser = lastUserIdx >= 0 ? i > lastUserIdx : i === messages.length - 1;
            return isTrailingUserSuffix || (role === 'assistant' && isAfterLastUser && isOpenPrefill(m));
        });
    }

    function collectPresetControlText(body, floor = null) {
        const msgText = collectPresetControlMessages(body, floor).map(m => getMsgText(m)).join('\n');
        if (msgText) return msgText;
        if (Array.isArray(body?.systemInstruction?.parts)) {
            return body.systemInstruction.parts.map(p => (typeof p?.text === 'string' ? p.text : '')).join('\n');
        }
        return '';
    }

    function hasKonatanPresetSignature(body, floor = null, presetText = null) {
        const txt = typeof presetText === 'string' ? presetText : collectPresetControlText(body, floor);
        return txt.includes('<konatan_planning~>') || txt.includes('<Output_format>') || txt.includes('<Storyboard_Blueprint>');
    }

    function hasTransAmPresetSignature(body, floor = null, presetText = null) {
        const txt = typeof presetText === 'string' ? presetText : collectPresetControlText(body, floor);
        // C-1: 仅匹配绝不进入聊天历史的预设控制层成对 <ta_rule_*> 标签或 [TA_NATIVE_DELIVERY]，剔除 <ta_zh> / <ta_plan> 输出标签，防止总结插件引用历史楼层时误命中
        return /<ta_rule_[a-z0-9_]+>[\s\S]*?<\/ta_rule_[a-z0-9_]+>/i.test(txt) || txt.includes('[TA_NATIVE_DELIVERY]');
    }

    function hasKnownStoryPresetSignature(body, floor = null, presetText = null) {
        const txt = typeof presetText === 'string' ? presetText : collectPresetControlText(body, floor);
        if (hasKonatanPresetSignature(body, floor, txt) || hasTransAmPresetSignature(body, floor, txt)) {
            return true;
        }
        if (txt.includes('<Interleaving>') && (txt.includes('<Interleaved_thinking>') || txt.includes('<thinking_format>'))) {
            return true;
        }
        return false;
    }

    // C-2: 独立用户楼层匹配（防 "好" / "继续" 等短词在总结/记忆插件转录提示中被子串误命中）
    function isStandaloneUserFloorMessage(items, floor = null) {
        if (!Array.isArray(items) || !items.length) return false;
        const resolvedFloor = floor && typeof floor === 'object' ? floor : readCurrentUserFloor();
        if (isFloorEmbeddedOnlyAsScriptData(items, resolvedFloor)) return false;
        const rawFloorTxt = typeof resolvedFloor?.text === 'string' ? resolvedFloor.text.trim() : '';
        const floorVars = rawFloorTxt ? textVariants(rawFloorTxt).map(v => v.trim()).filter(Boolean) : [];
        const isShortFloor = rawFloorTxt.length > 0 && rawFloorTxt.length < 12;
        const unwrapUserAnchor = s => String(s || '')
            .replace(/\{\{\s*LATEST_USER_INPUT\s*\}\}/g, '')
            .replace(/<audit_check\b[^>]*>[\s\S]*?<\/audit_check>/gi, '')
            .replace(/<\/?(?:latest_input|Master_input|interactive_input|本轮用户输入)\b[^>]*>/gi, '')
            .trim();

        for (let i = items.length - 1; i >= 0; i--) {
            const item = items[i];
            const role = String(item?.role || '').toLowerCase();
            if (role !== 'user') continue;
            const full = (Array.isArray(item?.parts)
                ? item.parts.map(p => (p && typeof p.text === 'string' ? p.text : '')).join('\n')
                : getMsgText(item)).trim();
            if (!full) continue;
            if (
                full.includes('{{LATEST_USER_INPUT}}')
                || /<(?:latest_input|Master_input|interactive_input|本轮用户输入)\b/i.test(full)
            ) {
                return true;
            }
            if (!floorVars.length) continue;
            const unwrapped = unwrapUserAnchor(full);
            if (isShortFloor) {
                // 短词必须整条独立用户消息完全相等，严禁走 includes 子串匹配
                if (floorVars.some(v => full === v || unwrapped === v)) {
                    return true;
                }
            } else if (floorVars.some(v => v.length >= 12 && (full.includes(v) || unwrapped.includes(v)))) {
                return true;
            }
        }
        return false;
    }

    function hasStructuredOrForcedToolLock(body) {
        if (!body || typeof body !== 'object') return false;
        if (body.json_schema || body.response_format || body.generationConfig?.responseSchema || body.generationConfig?.responseMimeType === 'application/json') {
            return true;
        }
        if (body.tool_choice !== undefined && body.tool_choice !== null && body.tool_choice !== 'auto' && body.tool_choice !== 'none') {
            return true;
        }
        const gMode = body.toolConfig?.functionCallingConfig?.mode;
