        }
        return '';
    }

    function isBaiBaiBookOrExplicitBypassPluginRequest(body) {
        if (!body || typeof body !== 'object') return false;
        if (classifyBaiBaiBookRequest(body)) return false;
        const rawType = body.type != null ? String(body.type).trim().toLowerCase() : '';
        const isNormalStoryType = rawType !== '' && ['normal', 'continue', 'swipe', 'regenerate', 'appendfinal'].includes(rawType);
        // 其余非柏宝书的声明式放行握手（如连通性测活或 Horae 等显式 tool_choice: 'none' 请求）保持原样放行
        if (body.tool_choice === 'none' && !isNormalStoryType && (!Array.isArray(body.tools) || body.tools.length === 0)) {
            return true;
        }
        return false;
    }

    function isPrimaryStoryTurnRequest(body, floor = null) {
        if (classifyBaiBaiBookRequest(body) || isBaiBaiBookOrExplicitBypassPluginRequest(body)) {
            return false;
        }
        const rawType = body && body.type != null ? String(body.type).trim().toLowerCase() : '';
        const thBusy = thGenerationActive();
        if (rawType && ['quiet', 'impersonate', 'dryrun', 'summarize', 'summary'].includes(rawType)) {
            return false;
        }
        if (hasStructuredOrForcedToolLock(body)) {
            return false;
        }
        const resolvedFloor = floor && typeof floor === 'object' ? floor : readCurrentUserFloor();
        const turns = Array.isArray(body?.messages) ? body.messages : (Array.isArray(body?.contents) ? body.contents : null);
        if (turns && isFloorEmbeddedOnlyAsScriptData(turns, resolvedFloor)) {
            return false;
        }
        const isGoogleNative = !Array.isArray(body?.messages) && Array.isArray(body?.contents);
        if (isGoogleNative) {
            if (thBusy) return false;
            if (Array.isArray(body?.tools) && body.tools.some(t => {
                if (Array.isArray(t?.functionDeclarations)) {
                    return t.functionDeclarations.some(fd => fd?.name && !isOwnTool(fd.name, SYNTHETIC_TOOL_NAME) && !EXCLUSIVE_CARRIER_TOOL_RX.test(fd.name));
                }
                const n = t?.function?.name || t?.name || '';
                return Boolean(n && !isOwnTool(n, SYNTHETIC_TOOL_NAME) && !EXCLUSIVE_CARRIER_TOOL_RX.test(n));
            })) {
                return false;
            }
            if (rawType) {
                return ['normal', 'continue', 'swipe', 'regenerate', 'appendfinal'].includes(rawType);
            }
            if (hasKnownStoryPresetSignature(body, resolvedFloor)) {
                return true;
            }
            const floorTxt = typeof resolvedFloor?.text === 'string' ? resolvedFloor.text.trim() : '';
            if (!floorTxt) {
                return true;
            }
            return isStandaloneUserFloorMessage(body.contents, resolvedFloor);
        }
        const hasType = rawType !== '';
        const hasSignature = hasKnownStoryPresetSignature(body, resolvedFloor);
        const isNormalType = hasType && ['normal', 'continue', 'swipe', 'regenerate', 'appendfinal'].includes(rawType);
        if (isNormalType) {
            return !thBusy || hasSignature;
        }
        // 当反代/前端请求省略了 body.type（hasType === false）且不在 thBusy 窗口（或具备明确的正文预设控制层签名）时，回退匹配独立用户楼层或预设签名
        if (!hasType && (!thBusy || hasSignature)) {
            return hasSignature || isStandaloneUserFloorMessage(body.messages, resolvedFloor);
        }
        return false;
    }

    function isPluginOnlyBypassStoryMode() {
        return runtime.settings.externalPluginEnabled === true && runtime.settings.externalPluginOnly === true;
    }

    function isMainGenerationRequest(body, cached = null) {
        const baiBaiKind = cached?.baiBaiKind !== undefined ? cached.baiBaiKind : classifyBaiBaiBookRequest(body);
        if (baiBaiKind) {
            // ComfyUI 工作流节点定位是纯技术 JSON 分析，无论走副 API 或主 API 一律原样放行
            if (baiBaiKind === 'baibai_image_workflow') return false;
            // 柏宝书与柏宝绘其余请求受「插件管理」开关控制：开启时进入对应防路由链路；关闭时原样放行
            return runtime.settings.externalPluginEnabled === true;
        }
        if (isBaiBaiBookOrExplicitBypassPluginRequest(body)) {
            return false;
        }
        const isStory = cached?.isStory !== undefined ? cached.isStory : isPrimaryStoryTurnRequest(body, cached?.floor || null);
        if (isPluginOnlyBypassStoryMode()) {
            // 开启「仅接管除正文以外的请求」时：正文反而不处理（返回 false 走原样放行），只接管非正文请求！
            return !isStory;
        }
        if (runtime.settings.externalPluginEnabled === true) {
            return true;
        }
        return isStory;
    }

    function estimateTextTokenCount(text) {
        if (typeof text !== 'string' || !text) return 0;
        let cjk = 0;
        let asciiWords = 0;
        let inAsciiWord = false;
        let asciiOther = 0;
        for (let i = 0; i < text.length; i++) {
            const code = text.charCodeAt(i);
            if (
                (code >= 0x3000 && code <= 0x9fff) ||
                (code >= 0xac00 && code <= 0xd7af) ||
                (code >= 0xff00 && code <= 0xffef)
            ) {
                cjk++;
                inAsciiWord = false;
            } else if ((code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122) || code === 95) {
                if (!inAsciiWord) {
                    asciiWords++;
                    inAsciiWord = true;
                } else {
                    asciiOther++;
                }
            } else {
                inAsciiWord = false;
                if (code > 32) asciiOther++;
            }
        }
        return Math.ceil(cjk * 1.15 + asciiWords * 1.15 + asciiOther * 0.35);
    }

    function estimateContentTokenCount(content) {
        if (typeof content === 'string') return estimateTextTokenCount(content);
        if (!Array.isArray(content)) return 0;
        let total = 0;
        for (let i = 0; i < content.length; i++) {
            const p = content[i];
            if (!p) continue;
            if (typeof p === 'string') total += estimateTextTokenCount(p);
            else if (typeof p.text === 'string') total += estimateTextTokenCount(p.text);
            else if (p.type === 'image_url' || p.image_url || p.inlineData || p.inline_data) total += 258;
        }
        return total;
    }

    function estimateRequestInputTokens(bodyObj) {
        if (!bodyObj || typeof bodyObj !== 'object') return 0;
        let total = 0;
        if (Array.isArray(bodyObj.messages)) {
            for (let i = 0; i < bodyObj.messages.length; i++) {
                const m = bodyObj.messages[i];
                if (!m || typeof m !== 'object') continue;
                total += 4 + estimateContentTokenCount(m.content);
                if (Array.isArray(m.tool_calls) && m.tool_calls.length > 0) {
                    try { total += estimateTextTokenCount(JSON.stringify(m.tool_calls)); } catch (_) {}
                }
            }
            total += 3;
        }
        if (bodyObj.systemInstruction) {
            total += estimateContentTokenCount(bodyObj.systemInstruction.parts || bodyObj.systemInstruction);
        }
        if (Array.isArray(bodyObj.contents)) {
            for (let i = 0; i < bodyObj.contents.length; i++) {
                const c = bodyObj.contents[i];
                if (!c || typeof c !== 'object') continue;
                total += 4 + estimateContentTokenCount(c.parts);
            }
        }
        if (Array.isArray(bodyObj.tools) && bodyObj.tools.length > 0) {
            try { total += estimateTextTokenCount(JSON.stringify(bodyObj.tools)); } catch (_) {}
        }
        return total;
    }

    function extractUsageStats(obj) {
        if (!obj || typeof obj !== 'object') return null;
        const out = {};
        if (obj.usage && typeof obj.usage === 'object') {
            const u = obj.usage;
            if (typeof u.prompt_tokens === 'number' && u.prompt_tokens >= 0) out.actualInputTokens = u.prompt_tokens;
            else if (typeof u.input_tokens === 'number' && u.input_tokens >= 0) out.actualInputTokens = u.input_tokens;
            const cached = u.prompt_tokens_details?.cached_tokens ?? u.cached_tokens ?? u.cache_read_input_tokens;
            if (typeof cached === 'number' && cached >= 0) out.cachedInputTokens = cached;
            if (typeof u.completion_tokens === 'number' && u.completion_tokens > 0) out.actualOutputTokens = u.completion_tokens;
            else if (typeof u.output_tokens === 'number' && u.output_tokens > 0) out.actualOutputTokens = u.output_tokens;
        }
        if (obj.message?.usage && typeof obj.message.usage === 'object') {
            const mu = obj.message.usage;
            if (out.actualInputTokens == null && typeof mu.input_tokens === 'number' && mu.input_tokens >= 0) out.actualInputTokens = mu.input_tokens;
            if (out.cachedInputTokens == null && typeof mu.cache_read_input_tokens === 'number' && mu.cache_read_input_tokens >= 0) out.cachedInputTokens = mu.cache_read_input_tokens;
            if (out.actualOutputTokens == null && typeof mu.output_tokens === 'number' && mu.output_tokens >= 0) out.actualOutputTokens = mu.output_tokens;
        }
        if (obj.usageMetadata && typeof obj.usageMetadata === 'object') {
            const um = obj.usageMetadata;
            if (typeof um.promptTokenCount === 'number' && um.promptTokenCount >= 0) out.actualInputTokens = um.promptTokenCount;
            if (typeof um.cachedContentTokenCount === 'number' && um.cachedContentTokenCount >= 0) out.cachedInputTokens = um.cachedContentTokenCount;
            if (typeof um.candidatesTokenCount === 'number' && um.candidatesTokenCount >= 0) {
                const thoughts = typeof um.thoughtsTokenCount === 'number' && um.thoughtsTokenCount >= 0 ? um.thoughtsTokenCount : 0;
                out.actualOutputTokens = um.candidatesTokenCount + thoughts;
            }
        }
        return Object.keys(out).length > 0 ? out : null;
    }

    function applyUsageToRun(run, obj) {
        if (!run || !obj || typeof obj !== 'object') return;
        const parsed = extractUsageStats(obj);
        if (parsed) {
            try { run.update(parsed); } catch (_) {}
        }
    }

    function policySnapshotCopy(policy) {
        if (!policy || typeof policy !== 'object') return null;
