                                ? 'event: content_block_delta\ndata: ' + JSON.stringify({ type: 'content_block_delta', index: 0, delta: { type: 'text_delta', text: combinedTail } }) + '\n\n'
                                : makeChunkLine({ content: combinedTail }, null);
