    function clearPanelStops() {
        drainStops(runtime.panelStops);
    }

    function syncConfigPanelViewport() {
        const panel = runtime.panel;
        const win = panel?.ownerDocument?.defaultView;
        if (!panel || !win) return;
        const vv = win.visualViewport;
        const h = vv ? Math.round(vv.height) : win.innerHeight;
        if (h > 0) panel.style.height = `${h}px`;
        if (vv) panel.style.top = `${Math.round(vv.offsetTop)}px`;
        else panel.style.top = '0px';
    }

    function closeConfigPanel() {
        const panel = runtime.panel;
        if (!panel) return;
        panel.classList.remove('open');
        try {
            if (runtime.lastFocusedElement && typeof runtime.lastFocusedElement.focus === 'function') {
                runtime.lastFocusedElement.focus();
            }
        } catch (_) {}
        runtime.lastFocusedElement = null;
    }

    function setToolTransport(enabled, options = {}) {
        const next = enabled === true;
        runtime.settings.toolTransport = next;
        saveSettings();
        syncStPostProcessingForToolTransport();
        syncConfigPanel();
        if (options.notify !== false) {
            notify('success', next ? '工具调用抗截断已开启' : '工具调用抗截断已关闭');
        }
        return next;
    }

    function setInputMode(mode, options = {}) {
        const allowed = ['json_escape', 'compact', 'hybrid_image', 'full_armor'];
        if (mode === 'off' || mode === false) {
            runtime.settings.inputEscapeEnabled = false;
        } else if (allowed.includes(mode)) {
            runtime.settings.inputMode = mode;
            if (options.autoEnable !== false) runtime.settings.inputEscapeEnabled = true;
        } else {
            return runtime.settings.inputMode;
        }
        saveSettings();
        syncConfigPanel();
        if (options.notify !== false) {
            const labels = {
                json_escape: '输入整包转义',
                compact: '输入码点转义',
                hybrid_image: '输入转图片',
                full_armor: '深度破盾',
            };
            notify('success', runtime.settings.inputEscapeEnabled ? `输入转义已切换：${labels[runtime.settings.inputMode] || runtime.settings.inputMode}` : '输入转义已关闭');
        }
        return runtime.settings.inputMode;
    }

    function renderRadioGroup(name, options, defaultVal) {
        return options.map(([val, label]) => (
            `<label class="tt-radio${val === defaultVal ? ' active' : ''}"><input type="radio" name="${name}" value="${val}"${val === defaultVal ? ' checked' : ''}><span>${label}</span></label>`
        )).join('');
    }

