        const handleClick = ev => {
            const tabEl = ev.target?.closest?.('[data-tab]');
            if (tabEl) {
                switchPanelTab(tabEl.dataset.tab);
                return;
            }
            if (ev.target === overlay || ev.target?.closest?.('[data-action="close"]')) {
                closeConfigPanel();
                return;
            }
            if (ev.target?.closest?.('[data-action="refreshModel"]')) {
                syncConfigPanel();
                const ctx = resolveModelContext(null, '');
                if (ctx.matchedProfile) {
                    notify('success', `已读取当前模型：${ctx.detectedModel}（匹配 ${ctx.matchedProfile.toUpperCase()}）`);
                } else {
                    notify('warning', ctx.detectedModel ? `通用模型：${ctx.detectedModel}` : '未读取到当前模型');
                }
                return;
            }
            if (ev.target?.closest?.('[data-action="salvageLast"]')) {
                salvageLastRawResponseIntoChat().catch(() => {});
                return;
            }
            if (ev.target?.closest?.('[data-action="clearLogs"]')) {
                runtime.runHistory.length = 0;
                runtime.lastRun = null;
                runtime.lastStoryRun = null;
                syncConfigPanel();
                notify('info', '已清空请求日志');
                return;
            }
            if (ev.target?.closest?.('[data-action="checkUpdate"]')) {
                checkForUpdate({ manual: true }).catch(() => {});
                return;
            }
            if (ev.target?.closest?.('[data-action="reloadForUpdate"]')) {
                if (runtime.activeRuns.size > 0) {
                    notify('warning', '当前仍有生成请求进行中，请稍候完成后再刷新');
                    return;
                }
                try { rootWindow()?.location?.reload?.(); } catch (_) {}
            }
        };

        const handleChange = ev => {
            const el = ev.target;
            if (!el) return;
            const role = el.getAttribute?.('data-role') || '';
            const name = el.getAttribute?.('name') || '';

            if (role === 'pluginEnabled') setPluginEnabled(el.checked);
            else if (role === 'storyThinkingLevel') {
                if (el.dataset.boundKey === 'otherThinkingLevel') setOtherThinkingLevel(el.value);
                else setHydrogenThinkingLevel(el.value);
            }
            else if (role === 'sanitizeThinkingConflict') setSanitizeThinkingConflict(el.checked);
            else if (role === 'extraInjectionEnabled') setExtraInjectionEnabled(el.checked);
            else if (role === 'autoBypassVertex') setAutoBypassVertex(el.checked);
            else if (name === 'tt-routing-level') setRoutingLevel(el.value);
            else if (role === 'jailbreakEnabled') setJailbreakEnabled(el.checked);
            else if (role === 'toolTransport') setToolTransport(el.checked);
            else if (role === 'inputEscapeEnabled') setInputEscapeEnabled(el.checked);
            else if (name === 'tt-input-mode') setInputMode(el.value, { autoEnable: false });
            else if (role === 'preserveTrailingPrefill') setPreserveTrailingPrefill(el.checked);
            else if (role === 'externalPluginEnabled') setExternalPluginEnabled(el.checked);
            else if (role === 'externalPluginOnly') setExternalPluginOnly(el.checked);
            else if (name === 'tt-ext-policy-mode') setExternalPluginPolicyMode(el.value);
            else if (role === 'pluginThinkingLevel') setPluginThinkingLevel(el.value);
            else if (name === 'tt-plugin-conflict') setPluginSanitizeThinkingConflict(el.value);
            else if (name === 'tt-plugin-extra-inj') setPluginExtraInjection(el.value);
            else if (name === 'tt-plugin-routing') setPluginRoutingLevel(el.value);
            else if (name === 'tt-plugin-jailbreak') setPluginJailbreak(el.value);
            else if (name === 'tt-plugin-input-mode') setPluginInputMode(el.value);
            else if (role === 'autoUpdateEnabled') setAutoUpdateEnabled(el.checked);
            else if (role === 'entryFloatingEnabled' || role === 'entryQrEnabled' || role === 'entryMenuEnabled') {
                const mapKey = role === 'entryFloatingEnabled' ? 'floating' : (role === 'entryQrEnabled' ? 'qr' : 'menu');
                const mapLabel = { floating: '悬浮窗入口', qr: '快捷栏入口', menu: '扩展菜单入口' }[mapKey];
                const res = setUiEntries({ [mapKey]: el.checked === true });
                if (res.ok) notify('success', `${mapLabel}已${el.checked ? '开启' : '关闭'}`);
            }
        };

        const handleEsc = ev => {
            if (ev.key === 'Escape' && overlay.classList.contains('open')) closeConfigPanel();
        };
        const handleResize = () => {
            if (overlay === runtime.panel) syncConfigPanelViewport();
        };

        const win = doc.defaultView;
        const vv = win?.visualViewport;
        overlay.addEventListener('click', handleClick);
        overlay.addEventListener('change', handleChange);
        doc.addEventListener('keydown', handleEsc, true);
        win?.addEventListener?.('resize', handleResize);
        vv?.addEventListener?.('resize', handleResize);

        runtime.panelStops.push(
            () => overlay.removeEventListener('click', handleClick),
            () => overlay.removeEventListener('change', handleChange),
            () => doc.removeEventListener('keydown', handleEsc, true),
            () => win?.removeEventListener?.('resize', handleResize),
            () => vv?.removeEventListener?.('resize', handleResize)
        );

        syncConfigPanelViewport();
        syncConfigPanel();
        return true;
    }

    function syncConfigPanel() {
        syncLauncherAppearance();
        const panel = runtime.panel;
        if (!panel) return;

        const cfg = runtime.settings;
        const masterOn = cfg.pluginEnabled !== false;
        const q = sel => panel.querySelector(sel);
        const setRadio = (groupName, val) => {
            panel.querySelectorAll(`input[name="${groupName}"]`).forEach(input => {
                const active = input.value === val;
                input.checked = active;
                input.closest('.tt-radio')?.classList.toggle('active', active);
            });
        };

        const masterSwitch = q('[data-role="pluginEnabled"]');
        if (masterSwitch) masterSwitch.checked = masterOn;
        q('[data-role="masterCard"]')?.classList.toggle('off', !masterOn);
        const masterState = q('[data-role="masterState"]');
        if (masterState) {
            masterState.textContent = masterOn ? '已开启' : '已关闭';
            masterState.className = `tt-chip${masterOn ? '' : ' warn'}`;
        }
        q('[data-role="headDot"]')?.classList.toggle('off', !masterOn);
        const headState = q('[data-role="headState"]');
        if (headState) headState.textContent = masterOn ? '运行中 · 按当前配置协同保护' : '已关闭 · 零改动原样直连';

        q('[data-role="subControlsWrap"]')?.classList.toggle('tt-disabled', !masterOn);
        q('[data-role="pluginControlsWrap"]')?.classList.toggle('tt-disabled', !masterOn);
        q('[data-role="pluginMasterOffBanner"]')?.classList.toggle('hide', masterOn);
        q('[data-role="storyPluginOnlyBanner"]')?.classList.toggle('hide', !(masterOn && isPluginOnlyBypassStoryMode()));

        // 模型识别状态
        const modelCtx = resolveModelContext(null, '');
        const prof = modelCtx.matchedProfile;
        const modelEl = q('[data-role="detectedModelDesc"]');
        if (modelEl) {
            modelEl.textContent = modelCtx.detectedModel || '未读取到当前模型';
            modelEl.title = modelCtx.detectedModel || '';
            modelEl.classList.toggle('muted', !modelCtx.detectedModel);
        }
        const archChip = q('[data-role="detectedArchChip"]');
        if (archChip) {
            if (prof) {
                archChip.textContent = `Gemini · ${prof.toUpperCase()}`;
                archChip.className = 'tt-chip';
            } else if (modelCtx.geminiFamily === 'no') {
                archChip.textContent = '非 Gemini';
                archChip.className = 'tt-chip blue';
            } else if (modelCtx.geminiFamily === 'yes') {
                archChip.textContent = 'Gemini · 通用';
                archChip.className = 'tt-chip';
            } else {
                archChip.textContent = '未知架构';
                archChip.className = 'tt-chip warn';
            }
        }

        // 思考等级
        const levelTable = {
            '4h': ['auto', 'low', 'medium', 'high', 'xhigh'],
            '4c': ['auto', 'low', 'medium', 'high'],
            '4n': ['auto', 'low', 'medium', 'high', 'xhigh'],
            '4a': ['auto', 'low', 'high'],
            '38f': ['auto', 'low', 'medium', 'high'],
        };
        const isMatchedProf = Boolean(prof && levelTable[prof]);
        const choices = isMatchedProf ? levelTable[prof] : ['auto', 'low', 'medium', 'high'];
        let curThink = isMatchedProf ? (cfg.hydrogenThinkingLevel || DEFAULTS.hydrogenThinkingLevel) : (cfg.otherThinkingLevel || DEFAULTS.otherThinkingLevel);
        if (!choices.includes(curThink)) {
            curThink = prof === '4a'
                ? ((curThink === 'high' || curThink === 'xhigh') ? 'high' : 'low')
                : (curThink === 'xhigh' ? 'high' : choices[0]);
        }
        const thinkSel = q('[data-role="storyThinkingLevel"]');
        if (thinkSel) {
            thinkSel.dataset.boundKey = isMatchedProf ? 'hydrogenThinkingLevel' : 'otherThinkingLevel';
            thinkSel.innerHTML = choices.map(v => `<option value="${v}">${v === 'auto' ? 'auto（默认）' : v}</option>`).join('');
            thinkSel.value = curThink;
        }
        const scopeChip = q('[data-role="thinkingScopeChip"]');
        if (scopeChip) {
            scopeChip.textContent = isMatchedProf ? prof.toUpperCase() : '通用';
            scopeChip.className = `tt-chip${isMatchedProf ? '' : ' gray'}`;
        }

        const setChecked = (role, val) => { const el = q(`[data-role="${role}"]`); if (el) el.checked = Boolean(val); };
        setChecked('autoBypassVertex', cfg.autoBypassVertex !== false);
        setChecked('sanitizeThinkingConflict', cfg.sanitizeThinkingConflict === true);
        setChecked('extraInjectionEnabled', cfg.extraInjectionEnabled !== false);
        setRadio('tt-routing-level', cfg.routingLevel || DEFAULTS.routingLevel);

        const jbOn = cfg.jailbreakEnabled !== false;
        setChecked('jailbreakEnabled', jbOn);
        q('[data-role="jailbreakSubBox"]')?.classList.toggle('tt-disabled', !jbOn);
        q('[data-role="jailbreakOffBadge"]')?.classList.toggle('hide', jbOn);
        setChecked('toolTransport', cfg.toolTransport === true);
        setChecked('inputEscapeEnabled', cfg.inputEscapeEnabled === true);
        q('[data-role="inputEscapeBox"]')?.classList.toggle('tt-disabled', cfg.inputEscapeEnabled !== true);
        setRadio('tt-input-mode', cfg.inputMode || DEFAULTS.inputMode);
        setChecked('preserveTrailingPrefill', cfg.preserveTrailingPrefill !== false);

        // 插件页
        const extOn = cfg.externalPluginEnabled !== false;
        const extMode = cfg.externalPluginPolicyMode === 'custom' ? 'custom' : 'follow';
        setChecked('externalPluginEnabled', extOn);
        setChecked('externalPluginOnly', cfg.externalPluginOnly === true);
        q('[data-role="externalPluginBox"]')?.classList.toggle('tt-disabled', !extOn);
        setRadio('tt-ext-policy-mode', extMode);
        q('[data-role="pluginCustomBox"]')?.classList.toggle('hide', !(extOn && extMode === 'custom'));

        const pluginChip = q('[data-role="pluginTabChip"]');
        if (pluginChip) {
            pluginChip.textContent = !extOn ? '关' : (cfg.externalPluginOnly ? '仅插件' : (extMode === 'custom' ? '单独' : '跟随'));
        }
        const pThink = q('[data-role="pluginThinkingLevel"]');
        if (pThink) pThink.value = cfg.pluginThinkingLevel || 'low';
        setRadio('tt-plugin-conflict', cfg.pluginSanitizeThinkingConflict || 'off');
        setRadio('tt-plugin-extra-inj', cfg.pluginExtraInjection || 'off');
        setRadio('tt-plugin-routing', cfg.externalPluginRoutingLevel || 'clean');
        setRadio('tt-plugin-jailbreak', cfg.externalPluginJailbreak || 'on');
        const pJbOff = cfg.externalPluginJailbreak === 'off' || (cfg.externalPluginJailbreak === 'follow' && !jbOn);
        q('[data-role="pluginInputOffNote"]')?.classList.toggle('hide', !pJbOff);
        q('[data-role="pluginInputRadios"]')?.classList.toggle('tt-disabled', pJbOff);
        setRadio('tt-plugin-input-mode', cfg.pluginInputMode || 'off');

        // 日志页
        const logs = runtime.runHistory || [];
        const logCnt = q('[data-role="logTabCount"]');
        if (logCnt) logCnt.textContent = String(logs.length);
        const logList = q('[data-role="logList"]');
        if (logList) {
            if (!logs.length) {
                logList.innerHTML = '<div class="tt-row-note">暂无请求日志。发起一次对话后会显示实时状态。</div>';
            } else {
                logList.innerHTML = logs.slice(0, 15).map(item => {
                    const t = new Date(item.time || Date.now()).toLocaleTimeString();
                    const dur = typeof item.duration === 'number' ? `${(item.duration / 1000).toFixed(1)}s` : '-';
                    const title = escapeHtml(formatRunTelemetryTag(item));
                    const tokens = item.finalInputTokens ? `输入约 ${item.finalInputTokens} tok` : '';
                    const outTok = item.estimatedOutputTokens ? ` · 输出约 ${item.estimatedOutputTokens} tok` : '';
                    const state = item.error
                        ? `异常: ${item.error}`
                        : item.phase === 'streaming'
                            ? '流式接收中'
                            : (item.phase === 'waiting-headers' || item.phase === 'waiting-body')
                                ? '等待响应'
                                : item.phase === 'cancelled'
                                    ? '已取消'
                                    : '完成';
                    return `<div class="tt-log-item"><div class="tt-log-top"><span>${title}</span><span>${escapeHtml(t)} · ${dur}</span></div><div class="tt-log-meta">${escapeHtml(state)}${tokens ? ' · ' + escapeHtml(tokens) : ''}${escapeHtml(outTok)}</div></div>`;
                }).join('');
            }
        }

        // 入口页
        const entries = getUiEntriesState();
        const enabledCount = [entries.floating, entries.qr, entries.menu].filter(Boolean).length;
        setChecked('entryFloatingEnabled', entries.floating);
        setChecked('entryQrEnabled', entries.qr);
        setChecked('entryMenuEnabled', entries.menu);
        const lockEl = (key, show) => {
            const el = q(`[data-role="entryLock-${key}"]`);
            if (el) el.style.display = show ? 'inline-flex' : 'none';
        };
        lockEl('floating', enabledCount === 1 && entries.floating);
        lockEl('qr', enabledCount === 1 && entries.qr);
        lockEl('menu', enabledCount === 1 && entries.menu);
        const entryCnt = q('[data-role="entryTabCount"]');
        if (entryCnt) entryCnt.textContent = String(enabledCount);
        try { updateFabStatus(); } catch (_) {}

        // 更新页
        setChecked('autoUpdateEnabled', cfg.autoUpdateEnabled === true);
        const updChip = q('[data-role="updateTabState"]');
        if (updChip) updChip.textContent = cfg.autoUpdateEnabled === true ? '开' : '关';
        const updDesc = q('[data-role="updateStatusDesc"]');
        const reloadBtn = q('[data-action="reloadForUpdate"]');
        const us = runtime.updateState || {};
        if (updDesc) {
            if (us.message) updDesc.textContent = us.message;
            else if (us.status === 'checking') updDesc.textContent = '正在检查最新版本…';
            else if (us.status === 'updated' || us.needsReload || us.applied) updDesc.textContent = `已更新至 v${us.latestVersion || VERSION}，刷新页面后生效。`;
            else if (us.status === 'up-to-date' || us.status === 'latest') updDesc.textContent = `当前 v${VERSION} 已是最新版本。`;
            else if (us.status === 'error') updDesc.textContent = `检查失败：${us.error || '网络异常'}`;
            else updDesc.textContent = `当前版本 v${VERSION}`;
        }
        if (reloadBtn) reloadBtn.style.display = (us.status === 'updated' || us.needsReload || us.applied) ? 'inline-block' : 'none';

        // 底部状态
        const footStatus = q('[data-role="status"]');
        if (footStatus) footStatus.textContent = runDescription();
    }

    function openConfigPanel() {
        if (!mountConfigPanel()) return false;
        const panel = runtime.panel;
        runtime.lastFocusedElement = panel.ownerDocument?.activeElement || null;
        syncConfigPanel();
        switchPanelTab(runtime.panelTab || 'story');
        syncConfigPanelViewport();
        panel.classList.add('open');
        return true;
    }

    // ==================== 悬浮球入口与酒馆助手工具栏接入 ====================

    function mountFallbackLauncher() {
        if (runtime.settings.entryFloatingEnabled === false) {
            unmountFallbackLauncher();
            return false;
        }
        const doc = hostDocument();
        if (!doc?.body) return false;
        unmountFallbackLauncher();

        if (!doc.getElementById(STYLE_ID)) {
            const styleEl = doc.createElement('style');
            styleEl.id = STYLE_ID;
            styleEl.dataset.instanceId = INSTANCE_ID;
            styleEl.textContent = configPanelCss();
            (doc.head || doc.documentElement).appendChild(styleEl);
            runtime.style = styleEl;
        }

        const btn = doc.createElement('button');
        btn.id = FALLBACK_LAUNCHER_ID;
        btn.dataset.instanceId = INSTANCE_ID;
        btn.type = 'button';
        btn.setAttribute('aria-label', '打开双马尾插件控制台（拖动可移动 / 右键切换开关）');

        const saved = readFabPos();
        let initialPos;
        if (saved && typeof saved.x === 'number' && typeof saved.y === 'number') {
            initialPos = clampFabPos(doc, saved.x, saved.y);
        } else {
            initialPos = defaultFabPos(doc);
        }
        placeFab(btn, initialPos);

        let dragCtx = null;
        let lastTapTs = 0;

        const onStart = ev => {
            if (ev.type === 'mousedown' && ev.button !== 0) return;
            const pt = ev.touches ? ev.touches[0] : ev;
            if (!pt) return;
            dragCtx = {
                startX: pt.clientX,
                startY: pt.clientY,
                baseX: parseFloat(btn.style.left) || 0,
                baseY: parseFloat(btn.style.top) || 0,
                dragged: false,
            };
        };

        const onMove = ev => {
            if (!dragCtx) return;
            const pt = ev.touches ? ev.touches[0] : ev;
            if (!pt) return;
            const dx = pt.clientX - dragCtx.startX;
            const dy = pt.clientY - dragCtx.startY;
            if (!dragCtx.dragged && Math.abs(dx) < 5 && Math.abs(dy) < 5) return;
            dragCtx.dragged = true;
            btn.classList.add('tt-dragging');
            if (ev.cancelable) ev.preventDefault();
            placeFab(btn, clampFabPos(doc, dragCtx.baseX + dx, dragCtx.baseY + dy));
        };

        const onEnd = () => {
            if (!dragCtx) return;
            const moved = dragCtx.dragged;
            dragCtx = null;
            btn.classList.remove('tt-dragging');
            if (moved) {
                saveFabPos(parseFloat(btn.style.left) || 0, parseFloat(btn.style.top) || 0);
                return;
            }
            const now = Date.now();
            if (now - lastTapTs < 320) return;
            lastTapTs = now;
            openConfigPanel();
        };

        const onRightClick = ev => {
            ev.preventDefault?.();
            ev.stopPropagation?.();
            setPluginEnabled(!(runtime.settings.pluginEnabled !== false));
        };

        btn.addEventListener('mousedown', onStart);
        btn.addEventListener('touchstart', onStart, { passive: true });
        btn.addEventListener('contextmenu', onRightClick);
        doc.addEventListener('mousemove', onMove);
        doc.addEventListener('touchmove', onMove, { passive: false });
        doc.addEventListener('mouseup', onEnd);
        doc.addEventListener('touchend', onEnd);
        doc.body.appendChild(btn);
        runtime.launcher = btn;
        syncLauncherAppearance();

        const checkTimer = setTimeout(() => {
            if (!btn.isConnected) return;
            const view = doc.defaultView;
            const vw = Number(view?.innerWidth || 0);
            const vh = Number(view?.innerHeight || 0);
            const r = btn.getBoundingClientRect();
            const offscreen = r.width < 8 || r.height < 8 || r.right <= 8 || r.left >= vw - 8 || r.bottom <= 8 || r.top >= vh - 8;
            if (!offscreen) return;
            const reset = defaultFabPos(doc);
            placeFab(btn, reset);
            saveFabPos(reset.x, reset.y);
        }, 650);

        runtime.floatingStops.push(() => {
            clearTimeout(checkTimer);
            btn.removeEventListener('mousedown', onStart);
            btn.removeEventListener('touchstart', onStart);
            btn.removeEventListener('contextmenu', onRightClick);
            doc.removeEventListener('mousemove', onMove);
            doc.removeEventListener('touchmove', onMove);
            doc.removeEventListener('mouseup', onEnd);
            doc.removeEventListener('touchend', onEnd);
        });
        return true;
    }

    function toolbarApi() {
        const bindFrom = (obj, fnName) => (typeof obj?.[fnName] === 'function' ? obj[fnName].bind(obj) : null);
        const candidates = [];
        try {
            const localTh = typeof TavernHelper !== 'undefined' ? TavernHelper : null;
            candidates.push({
                eventOn: typeof eventOn === 'function' ? eventOn : bindFrom(localTh, 'eventOn'),
                getButtonEvent: typeof getButtonEvent === 'function' ? getButtonEvent : bindFrom(localTh, 'getButtonEvent'),
                appendButtons: typeof appendInexistentScriptButtons === 'function'
                    ? appendInexistentScriptButtons
                    : (bindFrom(localTh, 'appendInexistentScriptButtons') || bindFrom(localTh, 'replaceScriptButtons')),
                getButtons: typeof getScriptButtons === 'function' ? getScriptButtons : bindFrom(localTh, 'getScriptButtons'),
                replaceButtons: typeof replaceScriptButtons === 'function' ? replaceScriptButtons : bindFrom(localTh, 'replaceScriptButtons'),
            });
        } catch (_) {}

        for (const win of hostWindows()) {
            try {
                const th = win?.TavernHelper || null;
                candidates.push({
                    eventOn: bindFrom(win, 'eventOn') || bindFrom(th, 'eventOn'),
                    getButtonEvent: bindFrom(win, 'getButtonEvent') || bindFrom(th, 'getButtonEvent'),
                    appendButtons: bindFrom(win, 'appendInexistentScriptButtons') || bindFrom(th, 'appendInexistentScriptButtons') || bindFrom(th, 'replaceScriptButtons'),
                    getButtons: bindFrom(win, 'getScriptButtons') || bindFrom(th, 'getScriptButtons'),
                    replaceButtons: bindFrom(win, 'replaceScriptButtons') || bindFrom(th, 'replaceScriptButtons'),
                });
            } catch (_) {}
        }

        return candidates.find(c => c.eventOn && c.getButtonEvent) || null;
    }

    function registerLauncher() {
        let hasThBtn = false;
        try {
            const api = toolbarApi();
            if (api) {
                if (api.getButtons && api.replaceButtons) {
                    const mig = migrateLegacyScriptButtons(api.getButtons());
                    if (mig.changed) {
                        try { api.replaceButtons(mig.buttons); } catch (_) {}
                    }
                }
                if (runtime.settings.entryQrEnabled !== false) {
                    try { api.appendButtons?.([{ name: LAUNCHER_BUTTON_NAME, visible: true }]); } catch (_) {}
                    hasThBtn = true;
                } else {
                    syncTavernScriptButtonVisibility(false);
                }
                const stop = api.eventOn(api.getButtonEvent(LAUNCHER_BUTTON_NAME), openConfigPanel);
                if (typeof stop === 'function') runtime.uiStops.push(stop);
                else if (stop && typeof stop.stop === 'function') runtime.uiStops.push(() => stop.stop());
            }
        } catch (err) {
            console.warn(`[${SCRIPT_NAME}] 注册酒馆脚本按钮失败`, err);
        }

        const hasFab = mountFallbackLauncher();
        const hasDirect = mountDirectQrAndMenuButtons();

        for (const delay of [450, 1400, 3000]) {
            const t = setTimeout(() => { if (!runtime.disposed) ensureDesktopFloatingVisible(); }, delay);
            runtime.uiStops.push(() => clearTimeout(t));
        }
        const poll = setInterval(() => {
            if (!runtime.disposed) ensureDesktopFloatingVisible();
        }, 4200);
        runtime.uiStops.push(() => clearInterval(poll));

        const doc = hostDocument();
        return [
            hasThBtn && 'th-qr',
            doc?.getElementById?.(QR_DOM_BTN_ID) && 'dom-qr',
            doc?.getElementById?.(EXT_MENU_ITEM_ID) && 'menu',
            hasFab && 'floating',
        ].filter(Boolean).join('+') || (hasDirect ? 'direct' : 'none');
    }

    // ==================== 对外 API、状态查询与生命周期 ====================

    function status() {
        return {
            version: VERSION,
            instanceId: INSTANCE_ID,
            installed: runtime.installed,
            activeRequests: runtime.activeRuns.size,
            settings: { ...runtime.settings },
            updateState: { ...runtime.updateState },
            capabilities: Array.from(runtime.capabilities.values(), item => ({ ...item })),
            lastRun: runtime.lastRun ? { ...runtime.lastRun } : null,
            lastStoryRun: runtime.lastStoryRun ? { ...runtime.lastStoryRun } : null,
            runHistory: runtime.runHistory.map(item => ({ ...item })),
        };
    }

